### 스텝 1 — 실패하는 통합 테스트 작성

- [ ] `tests/users.test.ts`를 아래 내용으로 작성한다. (register → login → get user → update user 전체 흐름)

```ts
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { buildTestApp } from './helpers/app.js';

describe('Users & Auth', () => {
  let app: FastifyInstance;

  // 각 실행마다 유일한 사용자
  const unique = Date.now();
  const username = `user${unique}`;
  const email = `user${unique}@example.com`;
  const password = 'password123';
  let token = '';

  beforeAll(async () => {
    app = await buildTestApp();
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
  });

  it('POST /api/users - 회원가입 성공', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/users',
      payload: { user: { username, email, password } },
    });
    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.user.username).toBe(username);
    expect(body.user.email).toBe(email);
    expect(body.user.token).toBeTypeOf('string');
    expect(body.user.bio).toBeNull();
    expect(body.user.image).toBeNull();
    expect(body.user.password).toBeUndefined();
  });

  it('POST /api/users - 필수 필드 누락 시 422', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/users',
      payload: { user: { email: 'x@x.com' } },
    });
    expect(res.statusCode).toBe(422);
    expect(res.json().errors).toBeDefined();
  });

  it('POST /api/users - 중복 email 시 422', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/users',
      payload: { user: { username: `${username}dup`, email, password } },
    });
    expect(res.statusCode).toBe(422);
    expect(res.json().errors.email).toEqual(['has already been taken']);
  });

  it('POST /api/users/login - 로그인 성공', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/users/login',
      payload: { user: { email, password } },
    });
    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.user.email).toBe(email);
    expect(body.user.token).toBeTypeOf('string');
    token = body.user.token;
  });

  it('POST /api/users/login - 잘못된 비밀번호 시 422', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/users/login',
      payload: { user: { email, password: 'wrong-password' } },
    });
    expect(res.statusCode).toBe(422);
    expect(res.json().errors['email or password']).toEqual(['is invalid']);
  });

  it('GET /api/user - 인증 없이 접근 시 401', async () => {
    const res = await app.inject({ method: 'GET', url: '/api/user' });
    expect(res.statusCode).toBe(401);
  });

  it('GET /api/user - 현재 사용자 조회', async () => {
    const res = await app.inject({
      method: 'GET',
      url: '/api/user',
      headers: { authorization: `Token ${token}` },
    });
    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.user.email).toBe(email);
    expect(body.user.username).toBe(username);
    expect(body.user.token).toBeTypeOf('string');
  });

  it('PUT /api/user - 사용자 정보 수정', async () => {
    const res = await app.inject({
      method: 'PUT',
      url: '/api/user',
      headers: { authorization: `Token ${token}` },
      payload: { user: { bio: 'I like to skateboard', image: 'https://i.stack.imgur.com/xHWG8.jpg' } },
    });
    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.user.bio).toBe('I like to skateboard');
    expect(body.user.image).toBe('https://i.stack.imgur.com/xHWG8.jpg');
    expect(body.user.email).toBe(email);
  });

  it('PUT /api/user - 비밀번호 변경 후 새 비밀번호로 로그인', async () => {
    const newPassword = 'new-password-456';
    const putRes = await app.inject({
      method: 'PUT',
      url: '/api/user',
      headers: { authorization: `Token ${token}` },
      payload: { user: { password: newPassword } },
    });
    expect(putRes.statusCode).toBe(200);

    const loginRes = await app.inject({
      method: 'POST',
      url: '/api/users/login',
      payload: { user: { email, password: newPassword } },
    });
    expect(loginRes.statusCode).toBe(200);
  });
});
