### 스텝 3 — `src/routes/users.ts` 전체 구현 (GREEN)

- [ ] 아래 코드로 `src/routes/users.ts`를 작성한다. (플레이스홀더 없음, 완전한 구현)

```ts
import type { FastifyInstance, FastifyReply } from 'fastify';
import { hashPassword, verifyPassword } from '../lib/password.js';

interface RegisterBody {
  user?: { username?: string; email?: string; password?: string };
}

interface LoginBody {
  user?: { email?: string; password?: string };
}

interface UpdateBody {
  user?: {
    email?: string;
    username?: string;
    password?: string;
    bio?: string;
    image?: string | null;
  };
}

// User 응답 조립 헬퍼
function toUserResponse(
  app: FastifyInstance,
  user: { id: number; email: string; username: string; bio: string | null; image: string | null },
) {
  return {
    user: {
      email: user.email,
      token: app.jwt.sign({ id: user.id, username: user.username }),
      username: user.username,
      bio: user.bio ?? null,
      image: user.image ?? null,
    },
  };
}

function unprocessable(reply: FastifyReply, errors: Record<string, string[]>) {
  return reply.code(422).send({ errors });
}

export default async function (app: FastifyInstance) {
  // 1) POST /api/users — 회원가입
  app.post<{ Body: RegisterBody }>('/users', async (req, reply) => {
    const user = req.body?.user ?? {};
    const { username, email, password } = user;

    const errors: Record<string, string[]> = {};
    if (!username) errors.username = ["can't be blank"];
    if (!email) errors.email = ["can't be blank"];
    if (!password) errors.password = ["can't be blank"];
    if (Object.keys(errors).length > 0) return unprocessable(reply, errors);

    // 중복 검사
    const dupErrors: Record<string, string[]> = {};
    const existingEmail = await app.prisma.user.findUnique({ where: { email } });
    if (existingEmail) dupErrors.email = ['has already been taken'];
    const existingUsername = await app.prisma.user.findUnique({ where: { username } });
    if (existingUsername) dupErrors.username = ['has already been taken'];
    if (Object.keys(dupErrors).length > 0) return unprocessable(reply, dupErrors);

    const hashed = await hashPassword(password!);
    const created = await app.prisma.user.create({
      data: { username: username!, email: email!, password: hashed },
    });

    return reply.code(200).send(toUserResponse(app, created));
  });

  // 2) POST /api/users/login — 로그인
  app.post<{ Body: LoginBody }>('/users/login', async (req, reply) => {
    const user = req.body?.user ?? {};
    const { email, password } = user;

    if (!email || !password) {
      return unprocessable(reply, { 'email or password': ['is invalid'] });
    }

    const found = await app.prisma.user.findUnique({ where: { email } });
    if (!found) {
      return unprocessable(reply, { 'email or password': ['is invalid'] });
    }

    const ok = await verifyPassword(password, found.password);
    if (!ok) {
      return unprocessable(reply, { 'email or password': ['is invalid'] });
    }

    return reply.code(200).send(toUserResponse(app, found));
  });

  // 3) GET /api/user — 현재 사용자 조회 (인증 필요)
  app.get('/user', { preHandler: app.authenticate }, async (req, reply) => {
    const found = await app.prisma.user.findUnique({ where: { id: req.user!.id } });
    if (!found) return reply.code(401).send({ errors: { user: ['not found'] } });
    return reply.code(200).send(toUserResponse(app, found));
  });

  // 4) PUT /api/user — 현재 사용자 정보 수정 (인증 필요)
  app.put<{ Body: UpdateBody }>('/user', { preHandler: app.authenticate }, async (req, reply) => {
    const patch = req.body?.user ?? {};

    const data: {
      email?: string;
      username?: string;
      password?: string;
      bio?: string;
      image?: string | null;
    } = {};

    if (patch.email !== undefined) data.email = patch.email;
    if (patch.username !== undefined) data.username = patch.username;
    if (patch.bio !== undefined) data.bio = patch.bio;
    if (patch.image !== undefined) data.image = patch.image;
    if (patch.password !== undefined && patch.password !== '') {
      data.password = await hashPassword(patch.password);
    }

    // email/username 변경 시 중복 검사
    const dupErrors: Record<string, string[]> = {};
    if (data.email) {
      const dup = await app.prisma.user.findUnique({ where: { email: data.email } });
      if (dup && dup.id !== req.user!.id) dupErrors.email = ['has already been taken'];
    }
    if (data.username) {
      const dup = await app.prisma.user.findUnique({ where: { username: data.username } });
      if (dup && dup.id !== req.user!.id) dupErrors.username = ['has already been taken'];
    }
    if (Object.keys(dupErrors).length > 0) return unprocessable(reply, dupErrors);

    const updated = await app.prisma.user.update({
      where: { id: req.user!.id },
      data,
    });

    return reply.code(200).send(toUserResponse(app, updated));
  });
}
```

