import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import Fastify, { type FastifyInstance } from 'fastify';
import '../src/types.js';
import errorsPlugin from '../src/plugins/errors.js';
import prismaPlugin from '../src/plugins/prisma.js';
import jwtPlugin from '../src/plugins/jwt.js';
import usersRoute from '../src/routes/users.js';

// autoload를 우회하여 users 라우트만 최소 앱으로 검증 (병렬 태스크의 미완성 라우트 영향 배제)
async function buildUsersApp(): Promise<FastifyInstance> {
  const app = Fastify({ logger: false });
  await app.register(errorsPlugin);
  await app.register(prismaPlugin);
  await app.register(jwtPlugin);
  await app.register(usersRoute, { prefix: '/api' });
  await app.ready();
  return app;
}

describe('Users & Auth (isolated)', () => {
  let app: FastifyInstance;
  const unique = Date.now();
  const username = `iso${unique}`;
  const email = `iso${unique}@example.com`;
  const password = 'password123';
  let token = '';

  beforeAll(async () => { app = await buildUsersApp(); });
  afterAll(async () => { await app.close(); });

  it('register 200', async () => {
    const res = await app.inject({ method: 'POST', url: '/api/users', payload: { user: { username, email, password } } });
    expect(res.statusCode).toBe(200);
    const b = res.json();
    expect(b.user.username).toBe(username);
    expect(b.user.token).toBeTypeOf('string');
    expect(b.user.bio).toBeNull();
    expect(b.user.password).toBeUndefined();
  });
  it('register missing field 422', async () => {
    const res = await app.inject({ method: 'POST', url: '/api/users', payload: { user: { email: 'x@x.com' } } });
    expect(res.statusCode).toBe(422);
  });
  it('register dup email 422', async () => {
    const res = await app.inject({ method: 'POST', url: '/api/users', payload: { user: { username: `${username}d`, email, password } } });
    expect(res.statusCode).toBe(422);
    expect(res.json().errors.email).toEqual(['has already been taken']);
  });
  it('login 200', async () => {
    const res = await app.inject({ method: 'POST', url: '/api/users/login', payload: { user: { email, password } } });
    expect(res.statusCode).toBe(200);
    token = res.json().user.token;
  });
  it('login wrong pw 422', async () => {
    const res = await app.inject({ method: 'POST', url: '/api/users/login', payload: { user: { email, password: 'nope' } } });
    expect(res.statusCode).toBe(422);
    expect(res.json().errors['email or password']).toEqual(['is invalid']);
  });
  it('get user 401 no auth', async () => {
    const res = await app.inject({ method: 'GET', url: '/api/user' });
    expect(res.statusCode).toBe(401);
  });
  it('get user 200', async () => {
    const res = await app.inject({ method: 'GET', url: '/api/user', headers: { authorization: `Token ${token}` } });
    expect(res.statusCode).toBe(200);
    expect(res.json().user.email).toBe(email);
  });
  it('update user 200', async () => {
    const res = await app.inject({ method: 'PUT', url: '/api/user', headers: { authorization: `Token ${token}` }, payload: { user: { bio: 'skate', image: 'http://x/y.jpg' } } });
    expect(res.statusCode).toBe(200);
    expect(res.json().user.bio).toBe('skate');
    expect(res.json().user.image).toBe('http://x/y.jpg');
  });
  it('change password then login', async () => {
    const np = 'new-pw-456';
    const put = await app.inject({ method: 'PUT', url: '/api/user', headers: { authorization: `Token ${token}` }, payload: { user: { password: np } } });
    expect(put.statusCode).toBe(200);
    const login = await app.inject({ method: 'POST', url: '/api/users/login', payload: { user: { email, password: np } } });
    expect(login.statusCode).toBe(200);
  });
});

